MMLU: Humanities & $-$0.31 [$-$0.85, 0.26] & No \\
MMLU: Social Sci & $-$0.57 [$-$1.05, $-$0.10] & Yes \\
\midrule
MMLU: Pooled & +0.11 [$-$0.40, 0.63] & No \\
ARC-Challenge & $-$1.46 [CI excl.\ 0] & Yes \\
GSM8K & +0.06 [CI incl.\ 0] & No \\
\bottomrule
\end{tabular}
\end{table}

