\label{tab:baselines}
\footnotesize
\resizebox{\columnwidth}{!}{%
\begin{tabular}{lcc|cc|cc}
\toprule
 & \multicolumn{2}{c|}{ARC} & \multicolumn{2}{c|}{GSM8K} & \multicolumn{2}{c}{MMLU} \\
Method & MAE & $\tau$ & MAE & $\tau$ & MAE & $\tau$ \\
\midrule
